mapper.select:
select 
from member_change_application a
left join reader_change_application r on r.application_id = a.id
left join employee_change_application e on e.application_id = a.id

    and a.application_type in
        ('READER_QUALIFICATION','READER_QUALIFICATION_RESTORE','BORROW_QUOTA_CHANGE')

    and a.id = #{query.id}

        and a.application_no = #{query.applicationNo}


        and a.applicant_member_id = #{query.applicantMemberId}


        and a.target_member_id = #{query.targetMemberId}


        and a.applicant_member_type = #{query.applicantMemberType}


        and a.application_type = #{query.applicationType}

    and a.status = #{query.status}

        and a.reviewer_member_id = #{query.reviewerMemberId}

    and a.created_at >= #{query.createdFrom}
    and a.created_at <= #{query.createdTo}

order by a.id desc

select count(*) from member_change_application
where target_member_id = #{targetMemberId}
  and application_type = #{applicationType}
  and status = 'PENDING'

select id
from member_change_application
where status = 'PENDING'
  and expires_at <= #{now}
order by expires_at, id
limit #{limit}

mapper.update:
update member_change_application
set status = 'EXPIRED',
    version = version + 1,
    updated_at = #{now}
where id = #{id}
  and status = 'PENDING'
  and version = #{expectedVersion}
  and expires_at <= #{now}

mapper.select:
select count(*)
from member_change_application
where target_member_id = #{memberId}
  and id <> #{excludeId}
  and status = 'PENDING'
  and application_type in ('READER_QUALIFICATION', 'READER_QUALIFICATION_RESTORE')

mapper.update:
update member_change_application
set status = 'CANCELLED', cancelled_at = current_timestamp,
    version = version + 1, updated_at = current_timestamp
where id = #{id} and applicant_member_id = #{applicantMemberId}
  and status = 'PENDING' and version = #{expectedVersion}
  and (expires_at is null or expires_at > #{now})

update member
set qualification_status = #{toStatus},
    accepted_rule_version = #{acceptedRuleVersion},
    version = version + 1, updated_at = current_timestamp
where id = #{memberId} and qualification_status = #{fromStatus}
  and version = #{expectedVersion}

update member
set account_status = #{toStatus}, version = version + 1,
    updated_at = current_timestamp
where id = #{memberId} and account_status = #{fromStatus}
  and version = #{expectedVersion}

update employee_profile
department_id = #{departmentId}, position_name = #{positionName}, version = version + 1
where member_id = #{memberId} and version = #{expectedVersion}

update employee_profile
set employment_status = #{toStatus}, left_on = #{leftOn},
    version = version + 1
where member_id = #{memberId} and employment_status = #{fromStatus}
  and version = #{expectedVersion}
